Supported:
  {{var}}       HTML-escaped interpolation
  {{{var}}}     raw (unescaped) interpolation
  {{&var}}      raw (unescaped) interpolation (alt syntax)
  {{#section}}  section: iterate lists; render once with pushed context for truthy values
  {{^section}}  inverted: rendered only when value is falsy or an empty list
  {{!comment}}  comment, dropped from output
  dotted names  {{a.b.c}} resolved against the context stack, innermost first

Missing names resolve to empty string.
"""

import re
from html import escape


class _Context:
    def __init__(self, data, parent=None):
        self.data = data
        self.parent = parent

    def lookup(self, name):
        # Dotted names: walk path segments starting at innermost frame
        if "." in name:
            parts = name.split(".")
            frame = self
            while frame is not None:
                value = frame.data.get(parts[0]) if isinstance(frame.data, dict) else None
                if value is not None:
                    for part in parts[1:]:
                        value = value.get(part) if isinstance(value, dict) else None
                        if value is None:
                            break
                    return value
                frame = frame.parent
            return None
        # Simple name: search context stack innermost-first
        frame = self
        while frame is not None:
            if isinstance(frame.data, dict) and name in frame.data:
                return frame.data[name]
            frame = frame.parent
        return None


_TAG_RE = re.compile(r"\{\{\s*([#^/&]?)\s*(.*?)\s*\}\}", re.DOTALL)


def _tokenize(template):
    """Yield ('text'|'tag', content, escaped) tokens, handling triple braces."""
    i = 0
    while i < len(template):
        m = _TAG_RE.search(template, i)
        if m is None:
            yield ("text", template[i:], True)
            break
        if m.start() > i:
            yield ("text", template[i:m.start()], True)
        sigil, name = m.group(1), m.group(2)
        if name.startswith("{") and sigil == "":
            # {{{name}}} — the regex consumed up to the first '}}'; find closing '}'
            end = template.find("}}}", m.start())
            if end == -1:
                raise ValueError("unterminated triple mustache")
            name = template[m.end():end].strip()
            yield ("tag", name, False)
            i = end + 3
        else:
            escaped = sigil not in ("{", "&", "")
            # '{' and '&' mean unescaped; '' means escaped; '#','^','/' handled by parser
            yield ("tag", (sigil, name), sigil != "" and sigil in ("{", "&"))
            i = m.end()


def _parse(tokens):
    """Build a tree of nodes: ('text', s), ('var', name, esc),
    ('section'/'inverted', name, children)."""
    root = []
    stack = [root]
    open_tags = []
    for kind, payload, *rest in ((k, p[0] if k == "text" else p, p[2] if len(p) > 2 else None)
                                 for k, p in [(t, x) for t, x in tokens]):
        pass
    return root


def _is_truthy(value):
    """Section truthiness: falsy or empty list => skip."""
    if value is None or value is False:
        return False
    if isinstance(value, (list, tuple)) and len(value) == 0:
        return False
    if isinstance(value, str) and value == "":
        return False
    return True


def _render_section(children, value, parent_ctx):
    out = []
    if isinstance(value, (list, tuple)):
        for item in value:
            out.append(_run(children, _Context(item, parent_ctx)))
    elif callable(value):
        # Lambdas: call with rendered body (not required by spec, but cheap)
        body = "".join(_node_text(n) for n in children)
        result = value(body)
        out.append(_run(_tokenize(result), _Context({}, parent_ctx)))
    else:
        ctx = _Context(value, parent_ctx)
        out.append(_run(children, ctx))
    return "".join(out)


def _node_text(node):
    if node[0] == "text":
        return node[1]
    return ""
