Supported:
  {{var}}       HTML-escaped interpolation
  {{{var}}}     raw (unescaped) interpolation
  {{&var}}      raw (unescaped) interpolation (alt syntax)
  {{#section}}  iterate lists; render once with pushed context for other truthy values;
                skipped when falsy or empty
  {{^section}}  rendered only when value is falsy (including empty list)
  {{!comment}}  dropped from output
  dotted names  {{a.b.c}} resolved against the context stack, innermost frame first

Missing names render as empty string. Public API: render(template, data) -> str.
"""

import re
from html import escape


class _Context:
    __slots__ = ("data", "parent")

    def __init__(self, data, parent=None):
        self.data = data
        self.parent = parent

    def lookup(self, name):
        parts = name.split(".")
        frame = self
        while frame is not None:
            if not isinstance(frame.data, dict):
                frame = frame.parent
                continue
            value = frame.data.get(parts[0])
            # Found at this level only if first segment exists here; otherwise
            # keep walking outward (shadowing: innermost wins).
            if parts[0] in frame.data:
                for part in parts[1:]:
                    value = value.get(part) if isinstance(value, dict) else None
                    if value is None:
                        break
                return value
            frame = frame.parent
        return None


_TAG_RE = re.compile(r"\{\{([^{}]*?)\}\}")


def _tokenize(template):
    """Yield ('text', s) and ('tag', sigil, name, escaped) tokens.

    Handles triple braces {{{name}}} as unescaped tags.
    """
    i = 0
    while i < len(template):
        m = _TAG_RE.search(template, i)
        if m is None:
            yield ("text", template[i:])
            break
        if m.start() > i:
            yield ("text", template[i:m.start()])
        inner = m.group(1).strip()
        if inner.startswith("{") and template[m.end():m.end() + 1] == "}":
            # triple mustache: '{{{' ... '}}}'
            yield ("tag", "{", inner[1:].strip(), False)
            i = m.end() + 1
        elif inner.startswith("&"):
            yield ("tag", "&", inner[1:].strip(), False)
            i = m.end()
        else:
            sigil = inner[0] if inner and inner[0] in "#^/" else ""
            name = inner[1:] if sigil else inner
            escaped = sigil not in ("#", "^", "/")
            yield ("tag", sigil, name.strip(), escaped)
            i = m.end()


def _parse(tokens):
    """Build node tree: ('text', s), ('var', name, esc),
    ('section', name, children), ('inverted', name, children)."""
    root = []
    stack = [root]
    open_names = []
    for tok in tokens:
        if tok[0] == "text":
            stack[-1].append(("text", tok[1]))
            continue
        _, sigil, name, _escaped = tok
        if sigil == "#":
            node = ("section", name, [])
            stack[-1].append(node)
            stack.append(node[2])
            open_names.append(name)
        elif sigil == "^":
            node = ("inverted", name, [])
            stack[-1].append(node)
            stack.append(node[2])
            open_names.append(name)
        elif sigil == "/":
            if not open_names or open_names[-1] != name:
                raise ValueError(f"unbalanced section close: {name!r}")
            open_names.pop()
            stack.pop()
        else:
            stack[-1].append(("var", name, tok[3]))
    if open_names:
        raise ValueError(f"unclosed section: {open_names[-1]!r}")
    return root


def _is_truthy(value):
    if value is None or value is False:
        return False
    if isinstance(value, str):
        return len(value) > 0
    if isinstance(value, (list, tuple, dict)):
        return len(value) > 0
    return True


def _run(nodes, ctx):
    out = []
    for node in nodes:
        kind = node[0]
        if kind == "text":
            out.append(node[1])
        elif kind == "var":
            value = ctx.lookup(node[1])
            text = "" if value is None else str(value)
            out.append(escape(text, quote=True) if node[2] else text)
        elif kind == "section":
            value = ctx.lookup(node[1])
            if _is_truthy(value):
                out.append(_render_section(node[2], value, ctx))
        elif kind == "inverted":
            value = ctx.lookup(node[1])
            if not _is_truthy(value):
                out.append(_run(node[2], ctx))
    return "".join(out)


def _render_section(children, value, ctx):
    if isinstance(value, (list, tuple)):
        return "".join(_run(children, _Context(item, ctx)) for item in value)
    return _run(children, _Context(value, ctx))


def render(template, data):
    """Render a Mustache template with the given data."""
    root = _parse(list(_tokenize(template)))
    return _run(root, _Context(data))
