from mustache import render


# --- interpolation ---------------------------------------------------------

def test_simple_escaped_var():
    assert render("Hello {{name}}!", {"name": "World"}) == "Hello World!"


def test_html_escaping():
    out = render("{{s}}", {"s": '<b>&"x"</b>'})
    assert out == '&lt;b&gt;&amp;&quot;x&quot;&lt;/b&gt;'


def test_triple_mustache_raw():
    assert render("{{{s}}}", {"s": "<i>raw</i>"}) == "<i>raw</i>"


def test_ampersand_raw():
    assert render("{{&s}}", {"s": "<i>raw</i>"}) == "<i>raw</i>"


def test_missing_key_renders_empty():
    assert render("a{{nope}}b", {"x": 1}) == "ab"


def test_non_string_value_is_stringified():
    assert render("{{n}}", {"n": 42}) == "42"


def test_dotted_name():
    assert render("{{a.b.c}}", {"a": {"b": {"c": "deep"}}}) == "deep"


def test_dotted_name_missing_intermediate():
    assert render("[{{a.b.c}}]", {"a": {}}) == "[]"


# --- sections --------------------------------------------------------------

def test_section_iterates_list_of_dicts():
    tpl = "{{#items}}<li>{{name}}</li>{{/items}}"
    data = {"items": [{"name": "a"}, {"name": "b"}, {"name": "c"}]}
    assert render(tpl, data) == "<li>a</li><li>b</li><li>c</li>"


def test_section_over_truthy_dict_pushes_context():
    # keys of the dict become visible inside without qualification
    tpl = "{{#person}}{{first}} {{last}}{{/person}}"
    data = {"person": {"first": "Ada", "last": "Lovelace"}}
    assert render(tpl, data) == "Ada Lovelace"


def test_falsy_section_skipped():
    assert render("{{#flag}}yes{{/flag}}", {"flag": False}) == ""
    assert render("{{#count}}shown{{/count}}", {"count": 0}) == ""


def test_inverted_on_empty_list():
    tpl = "<ul>{{#items}}<li>{{.}}</li>{{/items}}</ul>{{^items}}nothing here{{/items}}"
    assert render(tpl, {"items": []}) == "<ul></ul>nothing here"


def test_inverted_on_missing_and_false():
    assert render("{{^missing}}absent{{/missing}}", {}) == "absent"
    assert render("{{^f}}no{{/f}}", {"f": False}) == "no"
    assert render("{{^t}}no{{/t}}", {"t": True}) == ""


# --- context stack / shadowing ----------------------------------------------

def test_inner_section_key_shadows_outer():
    # 'name' exists both outside and inside; inner wins inside the section
    tpl = "{{name}}/{{#inner}}{{name}}{{/inner}}"
    data = {"name": "outer", "inner": {"name": "inner"}}
    assert render(tpl, data) == "outer/inner"


def test_section_falls_back_to_outer_context():
    # 'color' is not on the item; resolved from the enclosing context
    tpl = "{{#items}}{{color}} {{n}};{{/items}}"
    data = {"color": "red", "items": [{"n": 1}, {"n": 2}]}
    assert render(tpl, data) == "red 1;red 2;"


def test_dotted_name_uses_shadowing_stack():
    tpl = "{{#o1}}{{o1.y}}{{o2.y}}{{/o1}}"
    data = {"y": 0, "o1": {"y": 1}, "o2": {"y": 2}}
    assert render(tpl, data) == "12"


# --- comments & standalone lines --------------------------------------------

def test_comment_removed_mid_line():
    assert render("one {{! this is a comment }} two", {}) == "one  two"
    assert render("a{{!gone}}b", {}) == "ab"


def test_standalone_section_tag_lines_contribute_no_newline():
    tpl = "Items:\n{{#items}}\n- {{name}}\n{{/items}}\nDone."
    data = {"items": [{"name": "x"}, {"name": "y"}]}
    assert render(tpl, data) == "Items:\n- x\n- y\nDone."


def test_standalone_inverted_tag_line():
    tpl = "A\n{{^empty}}\nbody\n{{/empty}}\nB"
    assert render(tpl, {"empty": []}) == "A\nbody\nB"


def test_non_standalone_tags_keep_whitespace():
    # tags not alone on a line are rendered inline as usual
    tpl = "x {{#list}}*{{/list}} y"
    assert render(tpl, {"list": [1]}) == "x * y"
